// MergeFirewallRulesResource performs a merge with any union data inside the Resource, using the provided FirewallRulesResource
func (t *Resource) MergeFirewallRulesResource(v FirewallRulesResource) error {
	b, err := json.Marshal(v)
	if err != nil {
		return err
	}
	b, err = runtime.JSONMerge(b, []byte(`{"type":"nsx.policy"}`))
	if err != nil {
		return err
	}

	merged, err := runtime.JSONMerge(t.union, b)
	t.union = merged
	return err
}

// AsGroupMembershipResource returns the union data inside the Resource as a GroupMembershipResource
func (t Resource) AsGroupMembershipResource() (GroupMembershipResource, error) {
	var body GroupMembershipResource
	err := json.Unmarshal(t.union, &body)
	return body, err
}

// FromGroupMembershipResource overwrites any union data inside the Resource as the provided GroupMembershipResource
func (t *Resource) FromGroupMembershipResource(v GroupMembershipResource) error {
	b, err := json.Marshal(v)
	if err != nil {
		return err
	}
	b, err = runtime.JSONMerge(b, []byte(`{"type":"nsx.membership"}`))
	t.union = b
	return err
}

